// query: ?farmId=farm_0001&houseId=house1 (optional 필터)
const farmIdFilter = msg.req.query.farmId;
const houseIdFilter = msg.req.query.houseId;

const sched = global.get('scheduledOff') || {};
const now = Date.now();
const list = [];

for (const key of Object.keys(sched)) {
    const item = sched[key];
    if (!item || item.atMs <= now) continue;  // 만료된 잔재 스킵
    if (houseIdFilter && item.houseId !== houseIdFilter) continue;
    list.push({
        deviceId: item.deviceId,
        houseId: item.houseId,
        atMs: item.atMs,
        remainSec: Math.max(0, Math.floor((item.atMs - now) / 1000)),
        scheduledBy: item.scheduledBy || null,
        scheduledAt: item.scheduledAt || null,
    });
}

msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { success: true, data: list };
return msg;
